//! Phrases (crate::phrases): `take the integral of x^2
//! from 1 to 2`, `solve x^2 = 2 between 0 and 2 using bisection`, `take the
//! off-diagonal row sums of M`.
//!
//! lang/viv/tests/phrases/phrases.viv (generated by tools/phrases/cases.py)
//! has one test per phrase against the value NumPy or a closed form gives;
//! here it must cover every pattern of the table and pass, with the same
//! output, in the interpreter, as C and as wasm. The rest checks the rules:
//! `take` and the verbs stay names, a phrase that matches no pattern or
//! more than one reading is refused with the closest patterns or the
//! readings, a `fn` hole needs exactly one free variable, a hole read twice is
//! computed once, and a program with no phrase parses as it did.

use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::process::Command;

fn viv_bin() -> &'static str {
    env!("CARGO_BIN_EXE_viv")
}

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..").canonicalize().expect("the repo root")
}

fn cc() -> String {
    std::env::var("CC").unwrap_or_else(|_| "cc".to_string())
}

fn scratch(tag: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("viv_phrases_{}_{tag}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

#[derive(Debug, PartialEq)]
struct Ran {
    code: Option<i32>,
    out: String,
    err: String,
}

fn ran(o: std::process::Output) -> Ran {
    Ran {
        code: o.status.code(),
        out: String::from_utf8_lossy(&o.stdout).into_owned(),
        err: String::from_utf8_lossy(&o.stderr).into_owned(),
    }
}

fn interp(dir: &Path) -> Ran {
    ran(Command::new(viv_bin()).current_dir(dir).args(["run", "-q", "p.viv"]).output().unwrap())
}

fn native(dir: &Path) -> Option<Ran> {
    if Command::new(cc()).arg("--version").output().is_err() {
        return None;
    }
    let c = Command::new(viv_bin()).current_dir(dir).args(["p.viv", "-o", "p.c"]).output().unwrap();
    assert!(c.status.success(), "viv refused the program:\n{}", String::from_utf8_lossy(&c.stderr));
    let b = Command::new(cc()).current_dir(dir).args(["-std=c99", "-O0", "p.c", "-lm", "-o", "p"]).output().unwrap();
    assert!(b.status.success(), "the C did not build:\n{}", String::from_utf8_lossy(&b.stderr));
    Some(ran(Command::new(dir.join("p")).output().unwrap()))
}

/// The direct wasm backend in node, or None when there is no runtime to run it.
fn direct(dir: &Path) -> Option<Ran> {
    let wasm = std::env::var("VIV_WASM").map(PathBuf::from).unwrap_or_else(|_| root().join("www/public/viv/viv.wasm"));
    let bytes = std::fs::read(&wasm).ok()?;
    if !bytes.windows(12).any(|w| w == b"vrt_getslice") {
        eprintln!("skip wasm: {} has no slice runtime (www/build-wasm.sh builds one)", wasm.display());
        return None;
    }
    Command::new("node").arg("--version").output().ok()?;
    let c = Command::new(viv_bin()).current_dir(dir).args(["p.viv", "-o", "p.wasm"]).output().unwrap();
    assert!(c.status.success(), "the wasm backend refused the program:\n{}", String::from_utf8_lossy(&c.stderr));
    Some(ran(Command::new("node").arg(root().join("tools/run-wasm.mjs")).arg(dir.join("p.wasm")).env("VIV_WASM", &wasm).output().unwrap()))
}

/// Run `src` in every engine; they must agree byte for byte. Returns the
/// interpreter's run.
fn all(tag: &str, src: &str) -> Ran {
    let dir = scratch(tag);
    std::fs::write(dir.join("p.viv"), src).unwrap();
    let i = interp(&dir);
    assert_eq!(i.code, Some(0), "{tag}: the interpreter stopped:\n{}", i.err);
    if let Some(n) = native(&dir) {
        assert_eq!(i, n, "{tag}: interpreter and C disagree on\n{src}");
    }
    if let Some(w) = direct(&dir) {
        assert_eq!(i, w, "{tag}: interpreter and wasm disagree on\n{src}");
    }
    i
}

/// The refusal of `src`: the interpreter and the compiler both refuse it.
fn refused(tag: &str, src: &str) -> String {
    let dir = scratch(tag);
    std::fs::write(dir.join("p.viv"), src).unwrap();
    let c = ran(Command::new(viv_bin()).current_dir(&dir).args(["p.viv", "-o", "p.c"]).output().unwrap());
    assert_ne!(c.code, Some(0), "{tag}: the compiler accepted it");
    let i = ran(Command::new(viv_bin()).current_dir(&dir).args(["run", "-q", "p.viv"]).output().unwrap());
    assert_ne!(i.code, Some(0), "{tag}: the interpreter ran it");
    i.err
}

#[test]
fn every_pattern_has_a_case_that_passes_in_every_engine() {
    let path = root().join("lang/viv/tests/phrases/phrases.viv");
    let src = std::fs::read_to_string(&path).unwrap();
    let prog = viv::parse_keeping_rungs(&src, knotkit::span::SourceId(0)).unwrap();
    let used: HashSet<usize> = prog.phrases.iter().filter_map(|u| u.pattern).collect();
    let missing: Vec<String> = viv::phrases::TABLE.iter().enumerate().filter(|(i, _)| !used.contains(i)).map(|(_, p)| viv::phrases::written(p)).collect();
    assert!(missing.is_empty(), "patterns with no case in tools/phrases/cases.py: {missing:#?}");
    let r = all("cases", &src);
    let passes = r.out.lines().filter(|l| l.starts_with("PASS ")).count();
    let tests = src.lines().filter(|l| l.starts_with("test ")).count();
    assert_eq!(passes, tests, "{}", r.out);
    assert!(!r.out.contains("FAIL"), "{}", r.out);
}

#[test]
fn the_owners_three_examples() {
    let src = "\
c = 2.0
M = [[4.0, 1.0, 2.0], [1.5, 5.0, 3.0], [2.0, 3.5, 6.0]]
print(take the integral of x^2 from 1 to 2)
print(integrate x^2 from 1 to 2)
print(solve x^2 = c starting at 1 using newton)
print(solve x^2 - c between 0 and 2 using bisection)
print(take the sum of the off-diagonal entries of M)
print(take the off-diagonal row sums of M)
print(take the off-diagonal part of M)
print(sum the off-diagonal entries of each row of M)
";
    let r = all("owner", src);
    assert_eq!(
        r.out,
        "2.33333\n2.33333\n1.41421\n1.41421\n13\n[3, 4.5, 5.5]\n[[0, 1, 2], [1.5, 0, 3], [2, 3.5, 0]]\n[3, 4.5, 5.5]\n"
    );
}

#[test]
fn take_and_the_verbs_stay_names() {
    // a variable, a def and the builtin `take(a, idx, axis)` keep working
    let src = "\
take = 3.0
print(take + 1.0)
xs = [1.0, 2.0, 3.0]
print(take in xs)
print(take(xs, [2.0, 0.0], axis=0))
def solve(a) {
    return a * 2.0
}
print(solve(4.0))
integrate = 5.0
print(integrate - 1.0)
";
    let r = all("names", src);
    assert_eq!(r.out, "4\ntrue\n[3, 1]\n8\n4\n");
}

#[test]
fn a_program_without_phrases_parses_as_before() {
    let src = "def f(x) {\n    return x * 2.0\n}\ntake = 1.0\nshow f(take)\n";
    let a = format!("{:?}", viv::parse(src, knotkit::span::SourceId(0)).unwrap());
    assert!(!a.contains("phrases") && !a.contains("viv__ph"), "{a}");
    assert!(viv::parse(src, knotkit::span::SourceId(0)).unwrap().phrases.is_empty());
}

#[test]
fn a_hole_read_twice_is_computed_once() {
    // the median's lowering reads its hole four times; g() prints once
    let src = "\
def g() {
    print(\"g ran\")
    return [3.0, 1.0, 2.0, 5.0]
}
print(take the median of g())
print(take the unit vector along g())
";
    let r = all("once", src);
    assert_eq!(r.out, "g ran\n2.5\ng ran\n[0.480384, 0.160128, 0.320256, 0.800641]\n");
}

#[test]
fn the_variable_of_a_fn_hole() {
    // `T` is a parameter and `n` is assigned later in the loop: both are the
    // program's, so `t` is the variable; `with respect to` and `for` name it
    let src = "\
def boys0(T) {
    return take the integral of exp(-T * t * t) from 0 to 1 with 40 intervals
}
x = 3.0
total = 0.0
k = 0.0
while k < 2.0 {
    total = total + take the integral of n * s from 0 to 1
    n = k + 1.0
    k = k + 1.0
}
print(fmt(boys0(1.0), 12))
print(take the integral of x^2 with respect to x from 0 to 3)
print(fmt(solve x^2 = 2.0 for x between 0 and 2, 15))
";
    // only parsed: the loop reads `n` before it is first assigned; the point
    // is that the parse does not take `n` as the variable
    let prog = viv::parse(src, knotkit::span::SourceId(0)).unwrap();
    let vars: Vec<Option<String>> = prog.phrases.iter().map(|u| u.holes[0].var.clone()).collect();
    assert_eq!(vars, vec![Some("t".into()), Some("s".into()), Some("x".into()), Some("x".into())]);
}

#[test]
fn refusals_name_the_closest_phrases() {
    let e = refused("typo", "print(take the integrel of s^2 from 1 to 2)\n");
    assert!(e.contains("no phrase reads `take the integrel of s ^ 2 from 1 to 2`"), "{e}");
    assert!(e.contains("the closest phrases are `take the integral of F from A to B`"), "{e}");
    let e = refused("method", "print(take the root of s^2 - 2 between 0 and 2 using brent)\n");
    assert!(e.contains("`brent` is not a method this phrase knows; it knows `every method`, `bisection`, `illinois`, `regula falsi`, `false position`, `safeguarded secant`"), "{e}");
    let e = refused("newton", "print(solve s^2 - 1 using newton)\n");
    assert!(e.contains("Newton's method needs a point to start from: add `starting at x0`"), "{e}");
    let e = refused("tworeadings", "u = [1.0]\nv = [2.0]\nw = [3.0]\nprint(take the dot product of u and v and w)\n");
    assert!(e.contains("can be read 2 ways") && e.contains("U = `u`, V = `v and w`") && e.contains("U = `u and v`, V = `w`"), "{e}");
    let e = refused("twofree", "print(take the integral of a * s^2 from 1 to 2)\n");
    assert!(e.contains("`a * s ^ 2` has 2 free variables: `a`, `s`"), "{e}");
    let e = refused("nofree", "s = 1.0\nprint(take the integral of s^2 from 1 to 2)\n");
    assert!(e.contains("`s ^ 2` has no free variable") && e.contains("with respect to s"), "{e}");
    let e = refused("absent", "print(take the integral of s^2 with respect to y from 1 to 2)\n");
    assert!(e.contains("`y` does not appear in `s ^ 2`"), "{e}");
    let e = refused("twoeq", "print(solve s = 1 = 2 between 0 and 3)\n");
    assert!(e.contains("an equation in a phrase has one `=`"), "{e}");
}

#[test]
fn a_def_the_phrase_needs_cannot_be_replaced() {
    let src = "def r_bisect(f, a, b) {\n    return 0.0\n}\nprint(solve s^2 = 2 between 0 and 2 using bisection)\n";
    let e = refused("ownstd", src);
    assert!(e.contains("this program defines its own `r_bisect`, and a phrase calls the `r_bisect` of lang/viv/std/contracts.viv"), "{e}");
}

#[test]
fn viv_phrases_shows_each_phrase_as_a_call() {
    let dir = scratch("report");
    std::fs::write(dir.join("p.viv"), "c = 2.0\nr = take the root of x^2 = c between 0 and 2 using bisection\nshow r\n").unwrap();
    let o = ran(Command::new(viv_bin()).current_dir(&dir).args(["phrases", "p.viv"]).output().unwrap());
    assert_eq!(o.out, "   2  take the root of x^2 = c between 0 and 2 using bisection\n      = r_bisect(fn(x) -> x^2 - (c), 0, 2)\n      calls r_bisect (lang/viv/std)\n");
    let t = ran(Command::new(viv_bin()).args(["phrases", "--json"]).output().unwrap());
    let json = viv::story::parse_json(&t.out).unwrap();
    let n = json.get("count").and_then(|c| c.num()).unwrap();
    assert_eq!(n as usize, viv::phrases::TABLE.len());
}

#[test]
fn a_programs_own_phrases() {
    let r = all("ownfile", &std::fs::read_to_string(root().join("lang/viv/tests/phrases/own.viv")).unwrap());
    assert!(r.out.starts_with("8\n9.33333\n0.037037\n9.33333\nPASS "), "{}", r.out);
    // the report shows the body with the holes' text in it
    let dir = scratch("ownreport");
    std::fs::write(dir.join("p.viv"), "phrase \"the spread of v\" -> amax(v) - amin(v)\nprint(take the spread of [1.0, 4.0])\n").unwrap();
    let o = ran(Command::new(viv_bin()).current_dir(&dir).args(["phrases", "p.viv"]).output().unwrap());
    assert_eq!(o.out, "   2  take the spread of [1.0, 4.0]\n      = amax(([1.0, 4.0])) - amin(([1.0, 4.0]))  (the program's phrase `the spread of V`)\n");
}

#[test]
fn a_programs_own_phrases_are_checked() {
    let e = refused("dup", "phrase \"the sum of v\" -> sum(v)\n");
    assert!(e.contains("`take the sum of V` is already a phrase of Viv's table"), "{e}");
    let e = refused("twice", "phrase \"the spread of v\" -> amax(v) - amin(v)\nphrase \"the spread of w\" -> amax(w)\n");
    assert!(e.contains("`take the spread of W` is declared twice"), "{e}");
    let e = refused("sidebyside", "phrase \"the gap a b\" -> a - b\n");
    assert!(e.contains("`b` follows another hole"), "{e}");
    let e = refused("block", "def f() {\n    phrase \"the spread of v\" -> amax(v) - amin(v)\n    return 0.0\n}\n");
    assert!(e.contains("a phrase is declared at the top level"), "{e}");
    // the body reads the program's SCALE; inside a def with its own SCALE
    // the phrase would read that one instead, so it is refused
    let e = refused("hygiene", "SCALE = 2.0\nphrase \"the scaled v\" -> SCALE * v\ndef f(SCALE) {\n    return take the scaled 3.0\n}\nprint(f(1.0))\n");
    assert!(e.contains("reads the program's `SCALE`, and `SCALE` is a variable here"), "{e}");
    // a use that matches the program's phrase and one of the table is refused
    let e = refused("clash", "phrase \"the k of v\" -> k * v\nv = [3.0, 4.0]\nprint(take the norm of v)\n");
    assert!(e.contains("can be read 2 ways"), "{e}");
}

#[test]
fn a_phrase_has_the_content_address_of_its_call() {
    // the intent lens stamps a def by its body's hash: rewording a phrase, or
    // writing the call it lowers to, leaves the stamp as it was
    let def = |body: &str| format!("def f(v) {{\n    return {body}\n}}\nprint(f([1.0, 2.0]))\n");
    let hash = |src: &str| viv::def_hashes(src).unwrap().into_iter().find(|h| h.name == "f").map(|h| h.body_short).unwrap();
    let a = hash(&def("take the mean of v"));
    assert_eq!(a, hash(&def("take the average of v")));
    assert_eq!(a, hash(&def("mean(v)")));
    assert_ne!(a, hash(&def("take the median of v")));
}

/// The `x = b` of an equation phrase is not an assignment: after
/// `sol = solve A @ x = b`, `x` is still free for a later integral, and
/// `solve x = cos(x) ...` still solves for `x`.
#[test]
fn an_equation_in_a_phrase_assigns_nothing() {
    let r = all(
        "equation-not-assignment",
        "A = [[2.0, 0.0], [0.0, 4.0]]\nb = [2.0, 2.0]\nsol = solve A @ x = b\nprint(sol)\nprint(integrate x^2 from 0 to 1)\nprint(solve x = cos(x) between 0 and 1 using bisection)\n",
    );
    assert_eq!(r.out, "[1, 0.5]\n0.333333\n0.739085\n");
}
